impl DamageRegion {
	pub fn to_json(&self) -> String {
		let mut s = String::new();
		self.to_json_into(&mut s);
		s
	}
	pub fn to_text(&self) -> String {
		let mut s = String::new();
		self.to_text_into(&mut s);
		s
	}
	pub fn to_cbor(&self) -> Vec<u8> {
		let mut v = Vec::new();
		self.to_cbor_into(&mut v);
		v
	}
	pub fn to_json_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("\"whole\":");
		if self.whole {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push(',');
		out.push_str("\"rects\":");
		out.push('[');
		let mut v4 = true;
		for v3 in self.rects.iter() {
			if !v4 {
				out.push(',');
			}
			v4 = false;
			v3.to_json_into(out);
		}
		out.push(']');
		out.push('}');
	}
	pub fn to_text_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("whole=");
		if self.whole {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push_str(", ");
		out.push_str("rects=");
		out.push('[');
		let mut v6 = true;
		for v5 in self.rects.iter() {
			if !v6 {
				out.push_str(", ");
			}
			v6 = false;
			v5.to_text_into(out);
		}
		out.push(']');
		out.push('}');
	}
	pub fn to_cbor_into(&self, out: &mut Vec<u8>) {
		crate::codec::cbor::map(out, 2);
		crate::codec::cbor::text(out, "whole");
		crate::codec::cbor::boolean(out, self.whole);
		crate::codec::cbor::text(out, "rects");
		crate::codec::cbor::array(out, self.rects.len());
		for v7 in self.rects.iter() {
			v7.to_cbor_into(out);
		}
	}
}

